 bool SkillsInput(MouseState m)
 {
  var w=WindowAt(mouse);if(w?.Kind!=ViewMode.Skills||w.Minimized)return false;int wheel=m.ScrollWheelValue-oldMouse.ScrollWheelValue;if(wheel!=0){if(mouse.X>w.X+w.Width*.67f)skillQueueScroll=Math.Max(0,skillQueueScroll-wheel/120*3);else skillScroll=Math.Max(0,skillScroll-wheel/120*3);return true;}
  bool left=m.LeftButton==ButtonState.Pressed&&oldMouse.LeftButton==ButtonState.Released,right=m.RightButton==ButtonState.Pressed&&oldMouse.RightButton==ButtonState.Released,up=m.LeftButton==ButtonState.Released&&oldMouse.LeftButton==ButtonState.Pressed;
  var hit=ui.Hits.LastOrDefault(h=>h.Owner==w.Owner&&h.Rect.Contains(mouse.ToPoint()));
  if(right&&hit?.Tip.StartsWith("Skill row / ")==true){SkillMenu(int.Parse(hit.Tip[12..]));return true;}
  if(left&&hit?.Tip.StartsWith("Skill row / ")==true){skillDragId=int.Parse(hit.Tip[12..]);skillDragStart=mouse;skillSelected=skillDragId;return true;}
  if(left&&hit?.Tip.StartsWith("Skill queue / ")==true){skillDragQueue=int.Parse(hit.Tip[14..]);skillDragStart=mouse;return true;}
  if(skillDragId!=0){if(up){if(Vector2.Distance(mouse,skillDragStart)>8&&mouse.X>w.X+w.Width*.67f)SkillQueue(skillDragId,Math.Min(5,world.Skills.Trained(skillDragId)+1));else OpenSkillInfo(skillDragId);skillDragId=0;}return true;}
  if(skillDragQueue>=0){if(up){if(hit?.Tip.StartsWith("Skill queue / ")==true){int to=int.Parse(hit.Tip[14..]);skillNotice=world.Skills.Move(skillDragQueue,to)?"Queue reordered.":"Prerequisites prevent this order.";SkillSave();}skillDragQueue=-1;}return true;}
  if(right){ShowPopup("Skill queue",[("Pause / Resume",()=>{world.Skills.Advance(world.Now);world.Skills.Paused=!world.Skills.Paused;SkillSave();}),("Buy missing skillbooks",()=>SkillBooks(world.Skills.Queue.Select(q=>q.Skill))),("Save queue as plan",SaveQueuePlan)]);return true;}return false;
 }
