 void SkillPlanTransfer(bool import,bool clipboard){try{string path=Path.Combine(Path.GetDirectoryName(DemoWorld.SavePath)!,"skill-plan.json");if(import){string text=clipboard?FittingClipboard.Get():File.ReadAllText(path);var plan=System.Text.Json.JsonSerializer.Deserialize<SkillPlan>(text)??throw new InvalidDataException("Empty plan");if(plan.Entries.Count>10000||plan.Name.Length>100)throw new InvalidDataException("Plan too large");plan.Entries=new PilotSkills().Expand(plan.Entries.Select(e=>new SkillRequirement(e.Skill,e.Level)),false);plan.Id=Guid.NewGuid().ToString("N");plan.Certified=false;world.Skills.Plans.Add(plan);skillSelectedPlan=plan.Id;}else{var p=world.Skills.Plans.Single(p=>p.Id==skillSelectedPlan);string text=System.Text.Json.JsonSerializer.Serialize(p,new System.Text.Json.JsonSerializerOptions{WriteIndented=true});if(clipboard)FittingClipboard.Set(text);else File.WriteAllText(path,text);}skillNotice=import?"Plan imported.":"Plan exported.";SkillSave();}catch(Exception e){skillNotice=e.Message;}}
