 }
 void DrawSkillHistory(int x,int y,int width,int height){var history=world.Skills.History.AsEnumerable().Reverse().ToArray();int visible=Math.Max(1,height/26);skillScroll=Math.Clamp(skillScroll,0,Math.Max(0,history.Length-visible));foreach(string h in history.Skip(skillScroll).Take(visible)){ui.Text(ShortInfo(h,width/7),x,y,White,12);y+=26;}if(history.Length==0)ui.Text("Completed skill levels appear here.",x,y,Muted,14);}
 InformationEntry SkillInformation(int id){var s=SkillCatalog.ById[id];var e=new InformationEntry{Key="skill/"+id,Id="skill_"+id,Name=s.Name,Kind="Skill",Group="Skills / "+s.Group,MarketId="skill_"+id,Description=s.Description};e.Add("Description",s.Description);e.Add("Attributes","Training multiplier",s.Rank+"x");e.Add("Attributes","Primary attribute",SkillCatalog.AttributeNames[s.Primary]);e.Add("Attributes","Secondary attribute",SkillCatalog.AttributeNames[s.Secondary]);e.Add("Attributes","Training rate",world.Skills.Rate(id,world.Now).ToString("0.#")+" SP/min");e.Add("Attributes","Skill points",world.Skills.Points.GetValueOrDefault(id).ToString("N0"));for(int l=1;l<=5;l++)e.Add("Attributes","Level "+Roman(l),s.Threshold(l).ToString("N0")+" SP");e.Tab("Requirements");foreach(var t in SkillCatalog.Database.Types.Values.Where(t=>t.Requirements.Any(r=>r.Skill==id)).OrderBy(t=>t.Name)){string game=SkillCatalog.Database.GameTypes.FirstOrDefault(p=>p.Value==t.TypeId).Key??"";e.Add("Required For",game.Length>0?DemoWorld.ItemName(game):Retheme41.Index.Types.TryGetValue(t.TypeId,out var typeLore)?typeLore.Name:Retheme41.Text(t.Name),string.Join(", ",t.Requirements.Where(r=>r.Skill==id).Select(r=>Roman(r.Level))),game.Length>0?"item/"+game:"");}foreach(var (key,value) in s.Dogma)e.Add("Source",key,value.ToString("0.###"));e.Add("Source","Database build",SkillCatalog.Database.Build.ToString());return e;}
 List<InformationRow> SkillRequirementRows(string item){var roots=SkillCatalog.Required(item);var rows=new List<InformationRow>();var training=world.Skills.Expand(roots,false);rows.Add(new("Total Training Time",Duration(world.Skills.Seconds(training))));var seen=new HashSet<int>();void Add(SkillRequirement r,int depth){var s=SkillCatalog.ById[r.Skill];string state=world.Skills.Trained(r.Skill)>=r.Level?"Trained":world.Skills.Effective(r.Skill)>=r.Level?"Expert system":world.Skills.Injected.Contains(r.Skill)?"Injected":"Book missing";rows.Add(new(new string(' ',depth*3)+s.Name,Roman(r.Level)+" / "+state,"skill/"+r.Skill));if(depth<8&&seen.Add(r.Skill))foreach(var next in s.Requirements)Add(next,depth+1);}foreach(var root in roots)Add(root,0);if(roots.Length==0)rows.Add(new("No direct skill requirements."));return rows;}
 int DrawRequirementActions(InformationEntry e,DesktopWindow w,int x,int y,int width){if(w.InfoTab!="Requirements"&&e.Kind!="Skill")return y;if(e.Kind=="Skill"){int id=int.Parse(e.Id[6..]);ui.Button(new(x,y,width/3-4,27),"Train next level",()=>SkillQueue(id,Math.Min(5,world.Skills.Trained(id)+1)));ui.Button(new(x+width/3,y,width/3-4,27),"Buy / Inject",()=>SkillBooks([id]));ui.Button(new(x+width*2/3,y,width/3-4,27),"Apply SP",()=>SkillDo(()=>world.Skills.Apply(id,Math.Min(5,world.Skills.Trained(id)+1))));return y+34;}string item=e.Id=="player"?world.Player.CombatHull:e.Id;ui.Button(new(x,y,width/2-4,27),"Train requirements",()=>SkillDo(()=>world.QueueRequirements(item)));ui.Button(new(x+width/2,y,width/2-4,27),"Create skill plan",()=>CreateRequirementPlan(item));return y+34;}
}
